/*
 * Context-Aware Empathic Check-In: eEVA Project Studio entry point — v0.5 EVALUATION BUILD.
 *
 * This is NOT the frozen baseline. The frozen baseline is v0.4 (git tag v0.4-baseline-frozen,
 * branches baseline-v0.4 / baseline-v0.4-with-outputs); its counted trials and results must not
 * be compared with v0.5 output as if they were the same build.
 *
 * What v0.5 adds, for recording the four strategy vignettes for the user evaluation:
 *  - an operator-selected check-in strategy (the four VR-CoDES-P quadrants, strategies.js);
 *  - check-in wording generated by the platform LLM under that strategy, validated against the
 *    strategy's rules, with a clearly labelled template fallback (checkinPipeline.js);
 *  - an optional LLM verbal-concern classifier that understands negation and paraphrase, with
 *    the frozen v0.4 keyword matcher as a labelled fallback (verbalClassifier.js);
 *  - three input modes: LIVE (camera + mic), LIVE FACE + TYPED TEXT (STT fallback), and
 *    SIMULATED DEMO (synthetic AU4 + fixed transcript, always labelled as simulated);
 *  - approved ("frozen") lines per strategy, a recording view without operator labels, an
 *    optional fixed response delay, captions, an exported session log, and an AU capture tool.
 * The trigger is unchanged: AU4 peak >= 45 (trigger.js) AND a verbal cue.
 *
 * The project checker loads this file as CommonJS: run(context) and stop(context) are exposed
 * through module.exports. Upload main.js, trigger.js, config.json, eval_config.json,
 * strategies.js, llmAdapter.js, verbalClassifier.js and checkinPipeline.js together into src/.
 */

// Baseline settings: analyzer name, strategy list, values for the platform strategy helper.
const config = require("./config.json");
// v0.5 settings: defaults for the selectors, the canonical stimulus, timings, approved lines.
const evalConfig = require("./eval_config.json");
// The frozen decision constants (AU threshold, watched AUs). Not modified by v0.5.
const { CONFIG } = require("./trigger.js");
const { STRATEGY_IDS, STRATEGIES } = require("./strategies.js");
const { resolveLlm, callLlm } = require("./llmAdapter.js");
const {
  VERSION,
  INPUT_MODES,
  runScenario,
  toLogRecord,
  metricsDetail
} = require("./checkinPipeline.js");

// ---------------------------------------------------------------
// Shared state. Declared at module level so stop() can release it.
// ---------------------------------------------------------------

let recognizer = null;
let camera = null;
let silenceTimer = null;
let listenLimitTimer = null;
let finishListening = null;
let stopped = false;

// Incremented whenever the sensors are started or stopped, so an old analysis loop exits.
let sensorEpoch = 0;

// Elements added to the page directly when there is no overlay helper (removed in stop()).
let fallbackElements = [];

// True while the platform's runner controls are hidden by the recording view.
let runnerHidden = false;

const LISTEN_MAX_WAIT_MS = 8000;
const LISTEN_SILENCE_MS = 1200;

let speechEvents = 0;
let listenEndReason = null;
let onInterim = null;
let onAuFrame = null;

// localStorage key for operator-approved lines (per browser; export them to eval_config.json).
const APPROVALS_KEY = "sia32.v05.approvedUtterances";

// ---------------------------------------------------------------
// listenOnce: capture one spoken answer (unchanged from v0.4).
// ---------------------------------------------------------------
function listenOnce(silenceMs = LISTEN_SILENCE_MS, maxWaitMs = LISTEN_MAX_WAIT_MS) {
  return new Promise((resolve) => {
    let latest = "";
    let finished = false;
    listenEndReason = null;

    const end = (reason) => () => {
      if (finished) return;
      listenEndReason = reason;
      finishListening();
    };

    finishListening = () => {
      if (finished) return;
      finished = true;
      window.clearTimeout(silenceTimer);
      window.clearTimeout(listenLimitTimer);
      recognizer.stopRecognition();
      finishListening = null;
      resolve(latest.trim());
    };

    recognizer.startContinuousRecognition((transcript) => {
      speechEvents++;
      latest = transcript || "";
      onInterim?.(latest);
      window.clearTimeout(silenceTimer);
      silenceTimer = window.setTimeout(end("silence"), silenceMs);
    });

    listenLimitTimer = window.setTimeout(end("time_limit"), maxWaitMs);
  });
}

// ---------------------------------------------------------------
// Small DOM helpers.
// ---------------------------------------------------------------
function el(tag, props, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props || {})) {
    if (key === "style") node.style.cssText = value;
    else if (key === "text") node.textContent = value;
    else node[key] = value;
  }
  children.filter((c) => c != null).forEach((c) => node.append(c));
  return node;
}

function selectOf(options, value) {
  const sel = el("select", { style: "width:100%; padding:4px; font:inherit;" });
  options.forEach(([v, label]) => sel.append(el("option", { value: v, text: label })));
  if (options.some(([v]) => v === value)) sel.value = value;
  return sel;
}

function field(labelText, control) {
  return el("label", { style: "display:block; margin:0 0 6px; font-weight:600;" },
    el("span", { text: labelText, style: "display:block; font-size:11px; color:#4a5f52;" }),
    control);
}

// Platform pieces this module calls. The LLM and the platform strategy helper are optional
// (there are fallbacks) and are reported separately.
function findMissingPlatformPieces(context) {
  const h = context.helpers || {};
  const needed = [
    ["helpers.webcam.start", h.webcam?.start],
    ["helpers.biofeedback.analyzeVideo", h.biofeedback?.analyzeVideo],
    ["helpers.biofeedback.getTopAUs", h.biofeedback?.getTopAUs],
    ["helpers.wait", h.wait],
    ["AudioToText", typeof AudioToText === "undefined" ? undefined : AudioToText],
    ["context.agent.speak", context.agent?.speak],
    ["context.metrics.create", context.metrics?.create],
    ["context.ui.mountOverlay", context.ui?.mountOverlay]
  ];
  return needed.filter(([, piece]) => typeof piece !== "function").map(([name]) => name);
}

function loadLocalApprovals() {
  try {
    const raw = window.localStorage.getItem(APPROVALS_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (err) {
    return {};
  }
}

function saveLocalApprovals(approvals) {
  try {
    window.localStorage.setItem(APPROVALS_KEY, JSON.stringify(approvals));
    return true;
  } catch (err) {
    return false;
  }
}

// ---------------------------------------------------------------
// run: called by the platform when the project starts.
// ---------------------------------------------------------------
module.exports.run = async function run(context) {
  stopped = false;
  fallbackElements = [];

  const helpers = context.helpers;
  const llm = resolveLlm(context);
  const missingPieces = findMissingPlatformPieces(context);
  const hasPlatformStrategy = typeof helpers?.project?.createCheckInStrategy === "function";

  console.log("Context-Aware Empathic Check-In " + VERSION + " (evaluation build; frozen baseline is v0.4)");
  console.log("helpers:", Object.keys(helpers || {}));
  console.log("project helpers:", Object.keys(helpers?.project || {}));
  console.log("context:", Object.keys(context));
  console.log("LLM helper:", llm ? llm.name : "NOT FOUND (context.llm.generate / context.helpers.llm.generate)");
  if (missingPieces.length) console.warn("Missing platform pieces:", missingPieces.join(", "));
  if (!Array.isArray(config.strategies) || config.strategies.join() !== STRATEGY_IDS.join()) {
    console.warn("config.json strategies differ from strategies.js; v0.5 uses strategies.js:", STRATEGY_IDS);
  }

  const metrics = context.metrics?.create
    ? context.metrics.create("distress-check-in-v05")
    : { record: (...args) => console.log("[metric]", ...args) };

  const wait = (ms) => (typeof helpers?.wait === "function"
    ? helpers.wait(ms)
    : new Promise((resolve) => window.setTimeout(resolve, ms)));

  // Overlay mounting: platform overlay if available, otherwise the page.
  function mount(node) {
    if (typeof context.ui?.mountOverlay === "function") {
      context.ui.mountOverlay(node);
    } else {
      fallbackElements.push(node);
      (context.containerRef?.current || document.body).appendChild(node);
    }
  }

  // ---------------------------------------------------------------
  // State.
  // ---------------------------------------------------------------
  let busy = false;
  let recordingView = false;
  let lastRecord = null;
  const sessionLog = [];

  // Approved lines: eval_config.json first, then this browser's approvals on top.
  const configApprovals = {};
  for (const [id, value] of Object.entries(evalConfig.approvedUtterances || {})) {
    if (!STRATEGY_IDS.includes(id)) continue;
    const text = typeof value === "string" ? value : value && value.text;
    if (text) configApprovals[id] = { text, origin: (value && value.origin) || "eval_config.json" };
  }
  let localApprovals = loadLocalApprovals();
  const approvals = () => Object.assign({}, configApprovals, localApprovals);

  // ---------------------------------------------------------------
  // Operator panel.
  // ---------------------------------------------------------------
  const panel = el("section", {
    style:
      "top:16px; right:16px; left:auto; bottom:auto; transform:none; " +
      "width:min(460px, calc(100% - 32px)); max-height:calc(100% - 32px); overflow:auto; " +
      "padding:14px; border-radius:10px; background:white; color:#183322; " +
      "font:13px/1.4 system-ui, sans-serif; box-shadow:0 4px 18px rgba(0,0,0,.18); box-sizing:border-box;"
  });

  const title = el("div", { text: "Empathic Check-In " + VERSION + " (evaluation build)", style: "font-weight:700; font-size:15px;" });
  const modeBadge = el("div", { style: "margin:6px 0 10px; padding:4px 8px; border-radius:6px; font-weight:700; font-size:12px;" });

  const strategySel = selectOf(
    STRATEGY_IDS.map((id, i) => [id, (i + 1) + ". " + STRATEGIES[id].label + " (" + STRATEGIES[id].quadrant + ")"]),
    evalConfig.defaultStrategy
  );
  const inputSel = selectOf([
    ["live", "LIVE: camera AU4 + microphone"],
    ["live_face_typed_text", "LIVE FACE + TYPED TEXT (STT fallback)"],
    ["simulated", "SIMULATED DEMO: synthetic AU4 + fixed text"]
  ], INPUT_MODES.includes(evalConfig.defaultInputMode) ? evalConfig.defaultInputMode : "live");
  const verbalSel = selectOf([
    ["llm", "LLM classifier (keyword fallback)"],
    ["keywords", "Keywords only (v0.4 phrase list)"]
  ], evalConfig.defaultVerbalMode);
  const wordingSel = selectOf([
    ["llm", "LLM generated (template fallback)"],
    ["approved", "Approved line (frozen)"],
    ["template", "Template line (no LLM)"],
    ["platform_helper", "Platform createCheckInStrategy"]
  ], evalConfig.defaultGenerationMode);

  const transcriptInput = el("input", { type: "text", value: evalConfig.canonicalTranscript || "", style: "width:100%; padding:4px; font:inherit; box-sizing:border-box;" });
  const au4Input = el("input", { type: "number", min: 0, max: 100, step: 1, value: String(evalConfig.simulatedAu4 ?? 70), style: "width:90px; padding:4px; font:inherit;" });
  const delayInput = el("input", { type: "number", min: 0, max: 15000, step: 250, value: String(evalConfig.minResponseLatencyMs ?? 0), style: "width:90px; padding:4px; font:inherit;" });
  const captionsBox = el("input", { type: "checkbox" });

  const transcriptRow = field("Transcript (typed / fixed stimulus — used instead of speech-to-text)", transcriptInput);
  const au4Row = field("Synthetic AU4 value (0-100, SIMULATED, not a measurement)", au4Input);

  const btnStyle = "margin:4px 6px 0 0; padding:6px 10px; font:inherit; cursor:pointer;";
  const startButton = el("button", { type: "button", text: "Start scenario", disabled: true, style: btnStyle + "font-weight:700;" });
  const approveButton = el("button", { type: "button", text: "Approve last line", disabled: true, style: btnStyle });
  const recordingButton = el("button", { type: "button", text: "Recording view", style: btnStyle });
  const exportButton = el("button", { type: "button", text: "Export log", style: btnStyle });
  const testLlmButton = el("button", { type: "button", text: "Test LLM", style: btnStyle });
  const captureAuButton = el("button", { type: "button", text: "Capture AU (diagnostic)", style: btnStyle });
  const clearApprovalsButton = el("button", { type: "button", text: "Clear browser approvals", style: btnStyle });

  const statusLine = el("p", { text: "Starting...", style: "margin:8px 0; white-space:pre-line;" });
  const utteranceLine = el("p", { text: "", style: "margin:8px 0; padding:8px; background:#eef6f0; border-radius:6px; font-size:14px; display:none;" });
  const report = el("pre", { style: "margin:8px 0; padding:8px; background:#f6f7f6; border-radius:6px; white-space:pre-wrap; font:12px/1.35 ui-monospace, monospace; max-height:260px; overflow:auto;" });
  const diagnostics = el("p", { style: "margin:6px 0; font-size:12px; color:#4a5f52; white-space:pre-line;" });
  const approvalsList = el("div", { style: "font-size:12px; white-space:pre-line;" });
  const exportArea = el("textarea", { readOnly: true, style: "display:none; width:100%; height:140px; font:11px ui-monospace, monospace; box-sizing:border-box;" });
  const camHost = el("div");

  const approvalsBox = el("details", { style: "margin-top:8px;" },
    el("summary", { text: "Approved lines (used by \"Approved line\" wording)", style: "cursor:pointer; font-weight:600;" }),
    approvalsList, clearApprovalsButton);
  const diagnosticsBox = el("details", { style: "margin-top:8px;" },
    el("summary", { text: "Diagnostics", style: "cursor:pointer; font-weight:600;" }),
    diagnostics, testLlmButton, captureAuButton);

  const fullView = el("div", {},
    field("Check-in strategy (experimental condition)", strategySel),
    field("Input", inputSel),
    field("Verbal cue detector", verbalSel),
    field("Check-in wording", wordingSel),
    transcriptRow,
    au4Row,
    el("div", { style: "display:flex; gap:14px; align-items:center; flex-wrap:wrap; margin:4px 0;" },
      el("label", { style: "font-size:12px;" }, "Min. response delay (ms) ", delayInput),
      el("label", { style: "font-size:12px;" }, captionsBox, " Captions")),
    el("div", {}, startButton, approveButton, recordingButton, exportButton),
    statusLine,
    utteranceLine,
    report,
    approvalsBox,
    diagnosticsBox,
    exportArea,
    camHost
  );

  // Recording view: only the run and exit controls, no condition labels.
  const recRunButton = el("button", { type: "button", text: "Run", style: btnStyle + "font-weight:700;" });
  const recExitButton = el("button", { type: "button", text: "Exit recording view", style: btnStyle });
  const recBar = el("div", { style: "display:none;" }, recRunButton, recExitButton);

  panel.append(title, modeBadge, fullView, recBar);
  mount(panel);

  // Captions overlay (optional, for recordings).
  const caption = el("div", {
    style:
      "top:auto; bottom:28px; left:50%; right:auto; transform:translateX(-50%); " +
      "max-width:min(720px, calc(100% - 48px)); padding:8px 14px; border-radius:8px; " +
      "background:rgba(0,0,0,.72); color:white; font:18px/1.35 system-ui, sans-serif; " +
      "text-align:center; display:none;"
  });
  mount(caption);

  function showCaption(text) {
    if (!captionsBox.checked || !text) { caption.style.display = "none"; return; }
    caption.textContent = text;
    caption.style.display = "block";
  }

  // Status: the panel line, and the platform label only outside the recording view.
  const setStatus = (text) => {
    statusLine.textContent = text;
    if (!recordingView) context.settings?.labelElement?.(text);
  };

  function renderModeBadge() {
    const mode = inputSel.value;
    const styles = {
      live: ["LIVE: camera + microphone", "#d9f2e1", "#14532d"],
      live_face_typed_text: ["LIVE FACE + TYPED TEXT (not speech-to-text)", "#fff1c2", "#6b4e00"],
      simulated: ["SIMULATED DEMO: synthetic AU4 + fixed transcript (not live data)", "#ffd9d9", "#7a1010"]
    }[mode];
    modeBadge.textContent = styles[0];
    modeBadge.style.background = styles[1];
    modeBadge.style.color = styles[2];
    transcriptRow.style.display = mode === "live" ? "none" : "block";
    au4Row.style.display = mode === "simulated" ? "block" : "none";
  }

  function renderApprovals() {
    const all = approvals();
    approvalsList.textContent = STRATEGY_IDS.map((id, i) => {
      const a = all[id];
      return (i + 1) + ". " + STRATEGIES[id].quadrant + " " + id + ":\n   " +
        (a ? "\"" + a.text + "\" (" + (a.origin || "?") + (localApprovals[id] ? ", this browser" : ", eval_config.json") + ")" : "(none)");
    }).join("\n");
  }

  function renderDiagnostics(extra) {
    diagnostics.textContent = [
      "Version: " + VERSION + " | AU4 threshold: " + CONFIG.auThreshold + " | analyzer: " + analyzerEngine,
      "LLM helper: " + (llm ? llm.name : "not found -> classifier uses keywords_fallback, wording uses template_fallback"),
      "Camera/mic: " + (sensorsOn ? "running" : "off") + " | agent.speak: " + (typeof context.agent?.speak === "function" ? "yes" : "NO"),
      "Platform createCheckInStrategy: " + (hasPlatformStrategy ? "yes" : "no"),
      missingPieces.length ? "Missing: " + missingPieces.join(", ") : "All required platform pieces found.",
      extra || ""
    ].filter(Boolean).join("\n");
  }

  function setControlsEnabled(enabled) {
    [startButton, recRunButton, testLlmButton, captureAuButton, strategySel, inputSel, verbalSel, wordingSel]
      .forEach((c) => { c.disabled = !enabled; });
    approveButton.disabled = !enabled || !canApprove();
  }

  function canApprove() {
    return !!(lastRecord && lastRecord.utterance && lastRecord.generation &&
      !["approved", "safety_override"].includes(lastRecord.generation.source));
  }

  // ---------------------------------------------------------------
  // Facial AU analysis (unchanged logic from v0.4).
  // ---------------------------------------------------------------
  let peak = {};
  const resetPeak = () => {
    peak = {};
    CONFIG.facialAUs.forEach((id) => { peak[id] = 0; });
  };
  resetPeak();
  let listening = false;

  function extractCueAUs(aus) {
    const out = {};
    CONFIG.facialAUs.forEach((id) => { out[id] = 0; });
    const entries = helpers.biofeedback.getTopAUs(aus, 60) || [];
    for (const item of entries) {
      const id = String(parseInt(String(item.au).replace(/\D/g, ""), 10));
      if (id in out) out[id] = Math.max(out[id], Number(item.intensity) || 0);
    }
    return out;
  }

  const fmt = (n) => Number(n.toFixed(n >= 10 ? 1 : 2));
  const idOf = (label) => String(parseInt(label.replace(/\D/g, ""), 10));

  function createAuRecorder() {
    const peaks = {};
    const sums = {};
    let samples = 0;
    const nameOf = (label) => {
      const m = String(label).match(/(\d+)([LR])?/i);
      return m ? "AU" + parseInt(m[1], 10) + (m[2] ? m[2].toUpperCase() : "") : String(label);
    };
    function onFrame(rawAus) {
      samples++;
      if (samples === 1) console.log("[au_capture] raw analyzer result (first frame):", rawAus);
      const trialValues = {};
      (helpers.biofeedback.getTopAUs(rawAus, 100) || []).forEach((item) => {
        const v = Number(item.intensity);
        if (Number.isFinite(v)) {
          const name = nameOf(item.au);
          trialValues[name] = Math.max(trialValues[name] ?? -Infinity, v);
        }
      });
      const rawValues = {};
      const keepRaw = (label, value) => {
        const v = Number(value);
        if (!label || !Number.isFinite(v)) return;
        const name = nameOf(label);
        rawValues[name] = Math.max(rawValues[name] ?? -Infinity, v);
      };
      if (Array.isArray(rawAus)) {
        rawAus.forEach((item) => {
          keepRaw(String(item?.au ?? item?.name ?? item?.id ?? item?.label ?? ""),
                  item?.intensity ?? item?.value ?? item?.score);
        });
      } else if (rawAus && typeof rawAus === "object") {
        Object.entries(rawAus).forEach(([label, value]) => keepRaw(label, value));
      }
      const names = new Set([...Object.keys(trialValues), ...Object.keys(rawValues)]);
      names.forEach((name) => {
        const value = trialValues[name] ?? rawValues[name];
        peaks[name] = Math.max(peaks[name] ?? -Infinity, value);
        sums[name] = (sums[name] ?? 0) + value;
      });
    }
    function summary() {
      const labels = Object.keys(peaks).sort((a, b) => (idOf(a) - idOf(b)) || a.localeCompare(b));
      return {
        samples,
        rows: labels.map((label) => ({
          label,
          peak: fmt(peaks[label]),
          avg: fmt(sums[label] / samples),
          atOrAboveThreshold: CONFIG.facialAUs.includes(idOf(label)) && peaks[label] >= CONFIG.auThreshold
        }))
      };
    }
    return { onFrame, summary };
  }

  const analyzerEngine =
    (context.settings && context.settings.biofeedbackEngine) ||
    config.biofeedbackEngine ||
    "openface3";

  let sensorsOn = false;

  async function startSensors() {
    if (!helpers?.webcam || !helpers?.biofeedback) {
      throw new Error("helpers.webcam / helpers.biofeedback not exposed on context.helpers (see console)");
    }
    if (typeof AudioToText === "undefined") {
      throw new Error("AudioToText is not available in this project.");
    }
    const newCamera = await helpers.webcam.start(
      (context.containerRef && context.containerRef.current) || camHost,
      { overlay: true, width: 420, height: 315 }
    );
    if (stopped) { newCamera?.stop?.(); return false; }

    const newRecognizer = new AudioToText();
    await newRecognizer.initializeRecognizer();
    if (stopped) {
      newCamera?.stop?.();
      newRecognizer.stopRecognition?.();
      return false;
    }
    camera = newCamera;
    recognizer = newRecognizer;
    sensorsOn = true;
    sensorEpoch++;
    analysisLoop(sensorEpoch);
    renderDiagnostics();
    return true;
  }

  // Releases the camera and microphone (used when switching to SIMULATED, so a live camera
  // preview is never shown next to synthetic AU values).
  function stopSensors() {
    sensorEpoch++;
    sensorsOn = false;
    finishListening?.();
    recognizer?.stopRecognition?.();
    camera?.stop?.();
    recognizer = null;
    camera = null;
    renderDiagnostics();
  }

  async function analysisLoop(epoch) {
    const cam = camera;
    while (!stopped && epoch === sensorEpoch) {
      try {
        const result = await helpers.biofeedback.analyzeVideo(cam.video, analyzerEngine);
        if (stopped || epoch !== sensorEpoch) return;
        if (result && result.aus) {
          const latest = extractCueAUs(result.aus);
          if (listening) {
            CONFIG.facialAUs.forEach((id) => { peak[id] = Math.max(peak[id], latest[id]); });
            onAuFrame?.(result.aus);
          }
        }
      } catch (err) {
        if (stopped || epoch !== sensorEpoch) return;
        console.error("AU analysis failed:", err);
        await wait(500);
      }
      await wait(120);
    }
  }

  async function ensureSensors() {
    if (sensorsOn) return true;
    setStatus("Starting camera and microphone...");
    return startSensors();
  }

  // ---------------------------------------------------------------
  // Speech capture (unchanged from v0.4).
  // ---------------------------------------------------------------
  function transcriptFrom(raw) {
    if (typeof raw === "string") return raw.trim();
    if (raw && typeof raw === "object") {
      const t = raw.transcript ?? raw.text ?? "";
      return typeof t === "string" ? t.trim() : "";
    }
    return "";
  }

  async function captureLine() {
    speechEvents = 0;
    onInterim = (text) => { if (!stopped) setStatus("Hearing: \"" + text + "\""); };
    try {
      const probe = await navigator.mediaDevices.getUserMedia({ audio: true });
      probe.getTracks().forEach((t) => t.stop());
    } catch (err) {
      console.error("Microphone check failed:", err);
      throw new Error(
        "Microphone unavailable (" + (err && err.name ? err.name : err) +
        "). Allow the mic for this site, or switch Input to LIVE FACE + TYPED TEXT."
      );
    }
    if (stopped) return "";
    const heard = await listenOnce();
    if (heard || stopped) return heard;
    if (speechEvents === 0 && typeof context.speech?.listenOnce === "function") {
      console.warn("AudioToText produced no events; trying context.speech.listenOnce");
      setStatus("Retrying with the platform speech helper... say the line now.");
      try {
        return transcriptFrom(await context.speech.listenOnce({ timeoutMs: 8000 }));
      } catch (err) {
        console.error("context.speech.listenOnce failed:", err);
      }
    }
    return "";
  }

  // ---------------------------------------------------------------
  // Capture, per input mode. Each returns the pipeline input plus capture details.
  // ---------------------------------------------------------------
  async function captureLive() {
    resetPeak();
    const auRecorder = createAuRecorder();
    onAuFrame = auRecorder.onFrame;
    const windowStart = performance.now();
    listening = true;
    setStatus("Listening... say the line now.");
    let transcript = "";
    try {
      transcript = await captureLine();
    } finally {
      listening = false;
      onAuFrame = null;
      onInterim = null;
    }
    return {
      input: { aus: Object.assign({}, peak), transcript, inputMode: "live", facialSource: "live", transcriptSource: "stt" },
      capture: {
        windowMs: Math.round(performance.now() - windowStart),
        endReason: listenEndReason ?? "time_limit",
        speechEvents,
        ...auRecorder.summary()
      }
    };
  }

  async function captureTypedText() {
    const transcript = transcriptInput.value.trim();
    if (!transcript) throw new Error("Type the transcript first (LIVE FACE + TYPED TEXT mode).");
    const ms = Math.max(1000, Number(evalConfig.typedCaptureMs) || 5000);
    resetPeak();
    const auRecorder = createAuRecorder();
    onAuFrame = auRecorder.onFrame;
    listening = true;
    setStatus("Reading the face for " + (ms / 1000) + " s... perform the expression and say the line now.");
    showCaption("Student: " + transcript);
    try {
      await wait(ms);
    } finally {
      listening = false;
      onAuFrame = null;
    }
    return {
      input: { aus: Object.assign({}, peak), transcript, inputMode: "live_face_typed_text", facialSource: "live", transcriptSource: "typed" },
      capture: { windowMs: ms, endReason: "fixed_window", ...auRecorder.summary() }
    };
  }

  async function captureSimulated() {
    const transcript = transcriptInput.value.trim();
    const au4 = Number(au4Input.value);
    if (!transcript) throw new Error("Enter the fixed transcript first (SIMULATED mode).");
    if (!Number.isFinite(au4) || au4 < 0 || au4 > 100) throw new Error("Synthetic AU4 must be a number from 0 to 100.");
    const ms = Math.max(0, Number(evalConfig.simulatedStimulusMs) || 0);
    setStatus("SIMULATED stimulus (" + (ms / 1000) + " s)...");
    showCaption("Student: " + transcript);
    await wait(ms);
    return {
      input: { aus: { "4": au4 }, transcript, inputMode: "simulated", facialSource: "simulated", transcriptSource: "fixture" },
      capture: { windowMs: ms, endReason: "simulated", samples: 0, rows: [] }
    };
  }

  // ---------------------------------------------------------------
  // Scenario report (panel + console).
  // ---------------------------------------------------------------
  function showScenarioReport(record, capture) {
    const s = STRATEGIES[record.strategyId];
    const v = record.verbal || {};
    const g = record.generation || {};
    const yesNo = (b) => (b ? "true" : "false");
    const inputLabel = {
      live: "LIVE (camera AU4 + speech-to-text)",
      live_face_typed_text: "LIVE FACE + TYPED TEXT (transcript typed by operator)",
      simulated: "SIMULATED DEMO (synthetic AU4, fixed transcript; not a measurement)"
    }[record.inputMode];
    const lines = [
      "SCENARIO REPORT " + record.version,
      "Input: " + inputLabel,
      "Strategy: " + (STRATEGY_IDS.indexOf(record.strategyId) + 1) + ". " + record.strategyId + " (" + s.quadrant + "; target " + s.targetCodes + ")",
      "Transcript: " + (record.transcript ? "\"" + record.transcript + "\"" : "(none)") + " [" + record.transcriptSource + "]"
    ];
    if (record.inputMode !== "simulated" && capture) {
      lines.push(
        "Capture window: " + capture.windowMs + " ms, ended by " + capture.endReason,
        "Analyzer: " + analyzerEngine + " | samples: " + capture.samples
      );
      if (capture.rows && capture.rows.length) {
        lines.push("AU values (0-100):", ...capture.rows.map((r) =>
          "  " + r.label + ": " + r.peak + " Peak, " + r.avg + " Avg" + (r.atOrAboveThreshold ? " *" : "")));
      } else {
        lines.push("  (no AU readings received; check the camera and analyzer)");
      }
    }
    lines.push(
      "AU4 threshold: " + record.auThreshold + " | AU4 peak used: " +
        (record.au4Peak == null ? "none" : record.au4Peak.toFixed(1)) + (record.simulated ? " [SIMULATED]" : ""),
      "Facial cue: " + yesNo(record.facialCue),
      "Verbal detector: " + (v.source || "none") +
        (v.llmType ? " | LLM label: " + v.llmType + (v.rationaleShort ? " (" + v.rationaleShort + ")" : "") : "") +
        (v.fallbackReason ? " | fallback reason: " + v.fallbackReason : ""),
      "Keyword matcher (v0.4 list): " + yesNo(v.keywordVerbalCue) + " (" + ((v.matchedPhrases || []).join(", ") || "no phrases") + ")",
      "Verbal cue used: " + yesNo(record.verbalCue),
      "Decision: " + (record.shouldTrigger ? "CHECK IN" : "DO NOT CHECK IN")
    );
    if (record.shouldTrigger) {
      lines.push("Wording source: " + (g.source || "none") +
        (g.attempts ? " | attempts: " + g.attempts : "") +
        (g.latencyMs ? " | LLM " + g.latencyMs + " ms" : "") +
        (g.approvedOrigin ? " | approved from: " + g.approvedOrigin : ""));
      if (g.fallbackReason) lines.push("Wording fallback reason: " + g.fallbackReason);
      if (g.validationIssues && g.validationIssues.length) lines.push("Rejected LLM line issues: " + g.validationIssues.join("; "));
      if (g.templateMismatch) lines.push("WARNING: explicit template was written for \"" + evalConfig.canonicalTranscript + "\", not this transcript.");
      if (record.safetyOverride) lines.push("SAFETY OVERRIDE: crisis wording detected; fixed support line used. Follow the study safety procedure.");
      lines.push("Check-in: " + (record.utterance ? "\"" + record.utterance + "\"" : "(none)"),
        "Response delay: " + (record.responseLatencyMs == null ? "-" : record.responseLatencyMs + " ms") +
          " | spoken: " + yesNo(record.spoken));
    }
    if (record.error) lines.push("ERROR: " + record.error);
    if (record.aborted) lines.push("Stopped before the scenario finished.");
    report.textContent = lines.join("\n");
    console.log("[scenario_report_v05]", record, capture);
  }

  // ---------------------------------------------------------------
  // One scenario.
  // ---------------------------------------------------------------
  async function startScenario() {
    if (busy || stopped) return;
    busy = true;
    setControlsEnabled(false);
    if (recordingView) panel.style.visibility = "hidden";
    utteranceLine.style.display = "none";
    showCaption("");
    try {
      const inputMode = inputSel.value;
      let captured;
      if (inputMode === "simulated") {
        captured = await captureSimulated();
      } else {
        if (!(await ensureSensors())) return;
        captured = inputMode === "live" ? await captureLive() : await captureTypedText();
      }
      if (stopped) return;
      if (inputMode === "live" && captured.input.transcript) showCaption("Student: " + captured.input.transcript);

      const options = {
        strategyId: strategySel.value,
        verbalMode: verbalSel.value,
        generationMode: wordingSel.value,
        approvedUtterances: approvals(),
        templates: evalConfig.templates || {},
        canonicalTranscript: evalConfig.canonicalTranscript,
        llmTimeoutMs: Number(evalConfig.llmTimeoutMs) || 8000,
        maxGenerationAttempts: Number(evalConfig.maxGenerationAttempts) || 2,
        minResponseLatencyMs: Number(delayInput.value) || 0
      };
      const deps = {
        generate: llm ? llm.generate : null,
        wait,
        now: () => Date.now(),
        isStopped: () => stopped,
        onStage: (stage) => setStatus({
          classifying: "Checking the sentence...",
          generating: "Preparing the check-in...",
          speaking: "Agent is speaking."
        }[stage] || stage),
        platformStrategyUtterance: hasPlatformStrategy
          ? (id) => helpers.project.createCheckInStrategy(id).getUtterance({
              triggerSource: config.triggerSource,
              confidence: config.sampleConfidence
            })
          : null,
        speak: async (text) => {
          if (typeof context.agent?.speak !== "function") {
            throw new Error("context.agent.speak is not available in this project.");
          }
          utteranceLine.textContent = text;
          utteranceLine.style.display = "block";
          showCaption(text);
          await context.agent.speak(text);
        }
      };

      const record = await runScenario(captured.input, options, deps);
      record.capture = {
        windowMs: captured.capture.windowMs,
        endReason: captured.capture.endReason,
        samples: captured.capture.samples,
        analyzer: record.simulated ? "none (simulated)" : analyzerEngine
      };
      lastRecord = record;
      sessionLog.push(toLogRecord(record, { keepLiveTranscript: !!evalConfig.keepLiveTranscriptInLog }));
      metrics.record("trigger_decision_v05", record.shouldTrigger ? "check_in" : "no_check_in", metricsDetail(record));
      if (record.shouldTrigger) {
        metrics.record("check_in_v05", record.strategyId, "generation_source=" + (record.generation?.source || "none") + ";spoken=" + record.spoken);
      }
      if (stopped) return;
      showScenarioReport(record, captured.capture);
      setStatus(record.error ? "Finished with an error (see report)."
        : record.shouldTrigger ? "Done: check-in " + (record.spoken ? "spoken." : "not spoken.")
        : "Done: no check-in (gate not met).");
    } catch (err) {
      console.error("Scenario failed:", err);
      setStatus("Scenario error: " + (err && err.message ? err.message : err));
    } finally {
      listening = false;
      onAuFrame = null;
      busy = false;
      panel.style.visibility = "visible";
      if (!stopped) setControlsEnabled(true);
    }
  }

  // ---------------------------------------------------------------
  // Controls.
  // ---------------------------------------------------------------
  startButton.addEventListener("click", startScenario);
  recRunButton.addEventListener("click", startScenario);

  inputSel.addEventListener("change", () => {
    renderModeBadge();
    if (inputSel.value === "simulated" && sensorsOn) stopSensors();
    setStatus(inputSel.value === "simulated"
      ? "SIMULATED mode: camera and microphone are off."
      : "Camera and microphone start on the next scenario.");
  });

  approveButton.addEventListener("click", () => {
    if (!canApprove()) return;
    const r = lastRecord;
    localApprovals = Object.assign({}, localApprovals, {
      [r.strategyId]: {
        text: r.utterance,
        origin: r.generation.source,
        approvedAt: new Date().toISOString(),
        version: r.version,
        stimulus: r.transcriptSource === "stt" ? "[live speech]" : r.transcript
      }
    });
    const saved = saveLocalApprovals(localApprovals);
    renderApprovals();
    approvalsBox.open = true;
    setStatus("Approved for " + r.strategyId + (saved ? "." : " (this session only: browser storage unavailable)."));
  });

  clearApprovalsButton.addEventListener("click", () => {
    localApprovals = {};
    saveLocalApprovals(localApprovals);
    renderApprovals();
  });

  exportButton.addEventListener("click", () => {
    const data = {
      project: "CAP 5627 Team 3.2 empathic check-in",
      version: VERSION,
      exportedAt: new Date().toISOString(),
      auThreshold: CONFIG.auThreshold,
      approvedUtterances: approvals(),
      sessionLog
    };
    exportArea.value = JSON.stringify(data, null, 2);
    exportArea.style.display = "block";
    exportArea.select();
    console.log("[session_export_v05]", data);
  });

  recordingButton.addEventListener("click", () => setRecordingView(true));
  recExitButton.addEventListener("click", () => setRecordingView(false));

  function setRecordingView(on) {
    recordingView = on;
    fullView.style.display = on ? "none" : "block";
    recBar.style.display = on ? "block" : "none";
    title.style.display = on ? "none" : "block";
    modeBadge.style.display = on ? "none" : "block";
    panel.style.width = on ? "auto" : "min(460px, calc(100% - 32px))";
    panel.style.padding = on ? "6px" : "14px";
    panel.style.opacity = on ? "0.6" : "1";
    if (typeof context.ui?.setRunnerControlsVisible === "function") {
      context.ui.setRunnerControlsVisible(!on);
      runnerHidden = on;
    }
    if (!on) context.settings?.labelElement?.(statusLine.textContent);
  }

  testLlmButton.addEventListener("click", async () => {
    if (busy) return;
    busy = true;
    setControlsEnabled(false);
    renderDiagnostics("LLM test: waiting...");
    try {
      const res = await callLlm(llm ? llm.generate : null, "Reply with exactly the word OK and nothing else.", {
        timeoutMs: Number(evalConfig.llmTimeoutMs) || 8000
      });
      renderDiagnostics(res.ok
        ? "LLM test: OK in " + res.latencyMs + " ms, reply: \"" + res.text.slice(0, 80) + "\""
        : "LLM test FAILED (" + res.reason + "): " + res.error);
      console.log("[llm_test]", res);
    } finally {
      busy = false;
      if (!stopped) setControlsEnabled(true);
    }
  });

  // Capture AU: diagnostic only (replaces the v0.4 commented-out dry-run tool). Reads the face
  // for one listen window, lists every AU returned, never speaks, never logs to metrics.
  captureAuButton.addEventListener("click", async () => {
    if (busy || stopped) return;
    busy = true;
    setControlsEnabled(false);
    try {
      if (inputSel.value === "simulated") {
        setStatus("Capture AU needs the camera: switch Input to a LIVE mode first.");
        return;
      }
      if (!(await ensureSensors())) return;
      resetPeak();
      const rec = createAuRecorder();
      onAuFrame = rec.onFrame;
      listening = true;
      setStatus("Capture AU: hold the expression for " + (LISTEN_MAX_WAIT_MS / 1000) + " s...");
      await wait(LISTEN_MAX_WAIT_MS);
      listening = false;
      onAuFrame = null;
      if (stopped) return;
      const sum = rec.summary();
      report.textContent = ["CAPTURE AU (diagnostic, not a trial)",
        "Analyzer: " + analyzerEngine + " | samples: " + sum.samples + " | AU4 threshold: " + CONFIG.auThreshold,
        ...(sum.rows.length
          ? sum.rows.map((r) => "  " + r.label + ": " + r.peak + " Peak, " + r.avg + " Avg" + (r.atOrAboveThreshold ? " *" : ""))
          : ["  (no AU readings received)"])].join("\n");
      console.log("[capture_au_v05]", sum);
      setStatus("Capture AU finished.");
    } catch (err) {
      console.error("Capture AU failed:", err);
      setStatus("Capture AU error: " + (err && err.message ? err.message : err));
    } finally {
      listening = false;
      onAuFrame = null;
      busy = false;
      if (!stopped) setControlsEnabled(true);
    }
  });

  // ---------------------------------------------------------------
  // Setup.
  // ---------------------------------------------------------------
  renderModeBadge();
  renderApprovals();
  renderDiagnostics();
  try {
    if (inputSel.value !== "simulated") await startSensors();
    if (!stopped) setStatus("Ready (" + VERSION + "). Choose a strategy and click Start scenario.");
  } catch (err) {
    console.error("Webcam/recognizer setup failed:", err);
    setStatus("Setup failed: " + (err && err.message ? err.message : err) +
      " (Start scenario will try again, or switch Input to SIMULATED).");
  }
  if (!stopped) setControlsEnabled(true);

  // Keep run() open until the platform signals cleanup.
  await new Promise((resolve) => context.onCleanup(() => resolve()));
};

// ---------------------------------------------------------------
// stop: releases the microphone, camera, timers, speech, overlays and runner state.
// ---------------------------------------------------------------
module.exports.stop = async function stop(context) {
  stopped = true;
  sensorEpoch++;
  finishListening?.();
  window.clearTimeout(silenceTimer);
  window.clearTimeout(listenLimitTimer);
  recognizer?.stopRecognition();
  camera?.stop();
  recognizer = null;
  camera = null;
  context.agent?.stopSpeaking?.();
  context.agent?.neutral?.();
  if (runnerHidden) {
    context.ui?.setRunnerControlsVisible?.(true);
    runnerHidden = false;
  }
  context.ui?.clear?.();
  fallbackElements.forEach((node) => node.remove());
  fallbackElements = [];
};
